final class Money
{
    /** Tolerance scale for intermediate computations (well beyond the 6 digits of the rates). */
    public const SCALE = 16;

    public static function add(string $a, string $b): string
    {
        return bcadd($a, $b, self::SCALE);
    }

    public static function sub(string $a, string $b): string
    {
        return bcsub($a, $b, self::SCALE);
    }

    public static function mul(string $a, string $b): string
    {
        return bcmul($a, $b, self::SCALE);
    }

    public static function div(string $a, string $b): string
    {
        return bcdiv($a, $b, self::SCALE);
    }

    /** Round a non-negative value to 6 digits after the decimal point, HALF_UP. */
    public static function halfUp6(string $value): string
    {
        $value = bcdiv($value, '1', 30); // discard extra precision
        return bcdiv(bcadd($value, '0.0000005', 30), '1', 6);
    }

    /** Format exactly to 6 digits (for sums and deltas; truncation toward zero). */
    public static function to6(string $value): string
    {
        return bcdiv($value, '1', 6);
    }
}
