final class RateCalculator
{
    /**
     * Compute the exact cost of the event (rounded at the end to 6 digits, HALF_UP).
     *
     * @param array{unit: string, rates: array<string,string>} $price
     * @param array{input:int, output:int, cache_read:int, cache_write:int} $tokens
     */
    public function compute(array $price, array $tokens, ?OffPeak $offPeak, \DateTimeInterface $tsUtc): string
    {
        $cost = match ($price['unit']) {
            'per_1m_tokens' => $this->perToken($price['rates'], $tokens),
            'per_1m_tokens_unified' => $this->unified($price['rates'], $tokens),
            default => throw new \LogicException(sprintf('Unknown pricing unit "%s"', $price['unit'])),
        };

        if ($offPeak !== null && $offPeak->appliesAt(self::secondsMidnight($tsUtc))) {
            $cost = Money::mul($cost, $offPeak->multiplier);
        }

        return Money::halfUp6($cost);
    }

    private function perToken(array $rates, array $tokens): string
    {
        $kindMap = [
            'input' => $tokens['input'],
            'output' => $tokens['output'],
            'cache_read' => $tokens['cache_read'],
            'cache_write' => $tokens['cache_write'],
        ];
        $sum = '0';
        foreach ($kindMap as $rateKey => $tokensCount) {
            if ($tokensCount <= 0) continue; // actually zero*rate=0, can skip
            $sum = Money::add($sum, Money::div(Money::mul((string) $tokensCount, (string) $rates[$rateKey]), '1000000'));
        }
        return $sum;
    }

    private function unified(array $rates, array $tokens): string
    {
        $total = $tokens['input'] + $tokens['output'] + $tokens['cache_read'] + $tokens['cache_write'];
        if ($total <= 0) return '0';
        return Money::div(Money::mul((string) $total, (string) $rates['any']), '1000000');
    }

    public static function secondsMidnight(\DateTimeInterface $ts): int
    {
        return (int)$ts->format('H') * 3600 + (int)$ts->format('i') * 60 + (int)$ts->format('s');
    }
}
```

