```php
final class OffPeak
{
    private function __construct(
        private readonly int $windowStartSec,
        private readonly int $windowEndSec,
        private readonly string $multiplier,
    ) {}

    public static function fromProvider(?string $start, ?string $end, ?string $multiplier): ?self
    {
        if ($start === null || $end === null || $multiplier === null) {
            return null;
        }
        return new self(
            self::hhmmToSeconds($start),
            self::hhmmToSeconds($end),
            $multiplier,
        );
    }

    public function multiplier(): string
    {
        return $this->multiplier;
    }

    public function appliesAt(int $tsSecondsFromMidnight): bool
    {
        if ($this->windowStartSec === $this->windowEndSec) {
            return false;
        }

        if ($this->windowStartSec < $this->windowEndSec) {
            return $tsSecondsFromMidnight >= $this->windowStartSec
                && $tsSecondsFromMidnight < $this->windowEndSec;
        }

        return $tsSecondsFromMidnight >= $this->windowStartSec
            || $tsSecondsFromMidnight < $this->windowEndSec;
    }

    private static function hhmmToSeconds(string $hhmm): int
    {
        if (!preg_match('/^([01][0-9]|2[0-3]):[0-5][0-9]$/', $hhmm, $m)) {
            throw new \ValueError(sprintf('Некорректное время окна оф-пик: "%s"', $hhmm));
        }
        return ((int) $m[1]) * 3600 + ((int) substr($hhmm, -2)) * 60;
    }
}
